list_dashboards.code:
import com.webcommander.client.ApiResponse;
import java.util.List;
import java.util.Map;

ApiResponse response = client.dashboards().listDashboards();
Map<?, ?> body = (Map<?, ?>) response.getMap();
for (Object row : (List<?>) body.get("dashboards")) {
    Map<?, ?> dashboard = (Map<?, ?>) row;
    System.out.println(dashboard.get("id") + " " + dashboard.get("name") + " " + dashboard.get("default"));
}

